Once you have Kanna installed, you can use the following code to perform screen scraping:

```swift
import Foundation
import Kanna

func scrapeWebPage(url: URL, completion: @escaping (Result<[String], Error>) -> Void) {
    let task = URLSession.shared.dataTask(with: url) { data, response, error in
        guard let data = data, error == nil else {
            completion(.failure(error!))
            return
        }

        do {
            let doc = try Kanna(html: data, encoding: .utf8)
            var results: [String] = []

            // Replace the following selector with the one that matches the elements you want to scrape
            let elements = doc.css("div.class-name")

            for element in elements {
                // Replace the following code with the logic to extract the data you need
                let text = element.content!
                results.append(text)
            }

            completion(.success(results))
        } catch {
            completion(.failure(error))
        }
    }

    task.resume()
}

// Example usage:
let url = URL(string: "https://example.com")!
scrapeWebPage(url: url) { result in
    switch result {
    case .success(let results):
        print(results)
    case .failure(let error):
        print(error)
    }
}
```

Replace the `div.class-name` selector and the extraction logic with the ones that match the elements and data you want to scrape. Also, make sure to handle the results in the completion handler appropriately for your use case.

